/**
 * A stored rich-text document drawn through the vocabulary (`design/components/rich-text-content.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  RICH_TEXT_STOP,
  Ref,
  Render,
  agentMember,
  agentPress,
  bindSlot,
  cell,
  derived,
  elementRef,
  enterToolbar,
  followSelectionBar,
  getters,
  holdToolbarEscape,
  mapRichTextSelection,
  measured,
  mountEffect,
  placeSelectionBar,
  presence,
  provideOwner,
  richTextAnnotations,
  richTextDrawing,
  richTextKeyedAnnotation,
  richTextPressedAnnotation,
  richTextSelectionBox,
  serializeRichText,
  setup,
  slotDraws,
  syncToolbarStop,
  toolbarFocusIn,
  toolbarFocusOut,
  toolbarKeydown,
  toolbarPress,
  toolbarStop,
  useMember,
  watchEffect,
  type NodeTemplate,
  type RichTextDocument,
  type RichTextEntity,
  type RichTextRange,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import selectionBar from '@polymorph/recipes/controls/selection-bar.module.css'
import { RichTextContentBlocks, type RichTextContentBlocksProps } from './RichTextContentBlocks'

export type RichTextContentSize = NonNullable<RichTextContentProps['size']>

export interface RichTextContentSelection {
  range: RichTextRange
  text: string
}

export interface RichTextContentMessages {
  selectionBar?: string
  selectionBarReady?: string
}

/** A stored rich-text document drawn through the vocabulary: the inputs it takes, by the React member's prop names. */
export interface RichTextContentProps {
  /**
   * The drawn annotation that is active, such as the thread the app shows.
   */
  activeAnnotation?: string
  /**
   * The annotations drawn. Default: every one the document holds.
   */
  annotations?: string[]
  /**
   * The app's rendering of an entity: a Link to the person's page, a HoverCard with their card.
   * `undefined` draws the entity token, so an app can draw one kind itself and leave the others
   * as tokens.
   */
  entity?: NodeTemplate<[RichTextEntity]>
  /**
   * The page level the document's level 1 heading is drawn at. Each deeper level adds one, up to
   * 4. Default 2, one level under the page's title.
   */
  headingLevel?: 2 | 3 | 4
  /**
   * The selection bar's words, in the app's language.
   */
  messages?: RichTextContentMessages
  /**
   * The app's controls for the reader's selected text, in a bar at the selection.
   */
  selectionActions?: NodeTemplate<[RichTextContentSelection]>
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The stored document. Any JSON is read as far as it can be; what is not a document draws
   * nothing.
   */
  value: RichTextDocument
}

/** What RichTextContent hands its compound parts. */
export interface RichTextContentOwner {
  readonly size: Exclude<RichTextContentProps['size'], undefined>
  readonly pressable: unknown
  readonly routes: unknown
  readonly navigate: unknown
  readonly entityNode: unknown
}

/** A stored rich-text document drawn through the vocabulary. */
@Component({
  selector: 'pm-rich-text-content',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS, provideOwner('RichTextContent')],
  imports: [Ref, Render, RichTextContentBlocks],
  // prettier-ignore
  template: `<!-- root -->
<div
[attr.class]="e1()"
[attr.data-size]="e2()"
[attr.data-empty]="e3()"
data-member="rich-text-content"
(click)="h1($event)"
(keydown)="h2($event)"
(keyup)="h3($event)"
(pointerdown)="h4($event)"
[pmRef]="root"
>@if (e4()) {<pm-rich-text-content-blocks
[blocks]="e5()"
></pm-rich-text-content-blocks>}
@if (e6()) {<!-- selection bar -->
<div
[attr.class]="e7()"
role="toolbar"
[attr.aria-label]="e8()"
[attr.data-state]="e9()"
[attr.inert]="e10()"
(keydown)="h5($event)"
(focusin)="h6($event)"
(focusout)="h7($event)"
(mousedown)="h8($event)"
[pmRef]="bar"
><!-- actions -->
<div
[attr.class]="e11()"
(focusin)="h9($event)"
>@if (e12()) {<ng-container [pmRender]="e13()" />}</div></div>}
@if (e14()) {<!-- status -->
<div
[attr.class]="e15()"
role="status"
aria-live="polite"
[pmRef]="status"
>@if (e16()) {<span
[attr.key]="e17()"
>{{ e18() }}</span>}</div>}</div>`,
})
export class RichTextContent {
  /**
   * The drawn annotation that is active, such as the thread the app shows.
   */
  readonly activeAnnotation = input<RichTextContentProps['activeAnnotation']>(undefined)
  /**
   * The annotations drawn. Default: every one the document holds.
   */
  readonly annotations = input<RichTextContentProps['annotations']>(undefined)
  /**
   * The app's rendering of an entity: a Link to the person's page, a HoverCard with their card.
   * `undefined` draws the entity token, so an app can draw one kind itself and leave the others
   * as tokens.
   */
  readonly entity = input<RichTextContentProps['entity']>(undefined)
  /**
   * The page level the document's level 1 heading is drawn at. Each deeper level adds one, up to
   * 4. Default 2, one level under the page's title.
   */
  readonly headingLevel = input<RichTextContentProps['headingLevel']>(undefined)
  /**
   * The selection bar's words, in the app's language.
   */
  readonly messages = input<RichTextContentProps['messages']>(undefined)
  /**
   * The app's controls for the reader's selected text, in a bar at the selection.
   */
  readonly selectionActions = input<RichTextContentProps['selectionActions']>(undefined)
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  readonly size = input<
    Exclude<RichTextContentProps['size'], undefined>,
    RichTextContentProps['size']
  >('md', {
    transform: (value: RichTextContentProps['size']) => (value === undefined ? 'md' : value),
  })
  /**
   * The stored document. Any JSON is read as far as it can be; what is not a document draws
   * nothing.
   */
  readonly value = input.required<RichTextContentProps['value']>()
  /**
   * A press on a drawn annotation. Without it the highlights take no press and no focus.
   */
  readonly onAnnotationSelect = output<string>({ alias: 'annotationSelect' })
  /**
   * The app's router, handed to every Link the document draws (`link.md`).
   */
  readonly onNavigate = output<string>({ alias: 'navigate' })
  protected readonly $ = useMember({
    events: ['annotationSelect', 'navigate'],
    props: {
      activeAnnotation: () => this.activeAnnotation(),
      annotations: () => this.annotations(),
      entity: () => this.entity(),
      headingLevel: () => this.headingLevel(),
      messages: () => this.messages(),
      selectionActions: () => this.selectionActions(),
      size: () => this.size(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly selected = cell(() => ({
    now: null as { range: RichTextRange; text: string; key: string } | null,
    last: null as { range: RichTextRange; text: string; key: string } | null,
  }))
  protected readonly selecting = cell(() => false)
  protected readonly dismissed = cell(() => null as string | null)
  protected readonly barFocus = cell(() => false)
  protected readonly said = cell(() => ({ text: '', at: 0 }))
  protected readonly barHeard = cell(() => false)
  protected readonly bar = elementRef<HTMLElement>()
  protected readonly root = elementRef<HTMLElement>()
  protected readonly status = elementRef<HTMLElement>()
  protected readonly held = derived(() => ({
    range: null as Range | null,
    cameFrom: null as HTMLElement | null,
    restoring: false,
  }))
  protected readonly say = derived(() => ({
    selectionBar: this.$p.messages?.selectionBar ?? 'Selection',
    selectionBarReady:
      this.$p.messages?.selectionBarReady ?? 'Controls for the selection are available: Alt+F10',
  }))
  protected readonly pressable = derived(() =>
    this.$.listening(this.onAnnotationSelect, 'onAnnotationSelect'),
  )
  protected readonly routes = derived(() => this.$.listening(this.onNavigate, 'onNavigate'))
  protected readonly navigate = derived(
    () => (href: string) => this.$.emit(this.onNavigate, 'onNavigate', href),
  )
  protected readonly entityNode = measured(
    () => (drawn: RichTextEntity) => bindSlot(this.$p.entity, drawn),
  )
  protected readonly mapped = measured(() => !!(this.$p.selectionActions !== undefined))
  protected readonly appDraws = measured(
    () => (drawn: RichTextEntity) => slotDraws(this.$p.entity, drawn),
  )
  protected readonly drawing = derived(() =>
    richTextDrawing(this.$p.value, {
      headingLevel: this.$p.headingLevel,
      annotations: this.$p.annotations,
      activeAnnotation: this.$p.activeAnnotation,
      pressable: this.pressable.value,
      positions: this.mapped.value,
      appDraws: this.appDraws.value,
    }),
  )
  protected readonly drawn = derived(
    () => (id: string) => this.$p.annotations === undefined || this.$p.annotations.includes(id),
  )
  protected readonly offering = derived(() => this.mapped.value && !this.drawing.value.empty)
  protected readonly docKey = derived(() =>
    this.offering.value ? serializeRichText(this.drawing.value.value) : '',
  )
  protected readonly shown = derived(
    () => this.selected.value.now ?? (this.barFocus.value ? this.selected.value.last : null),
  )
  protected readonly barOpen = derived(
    () =>
      this.offering.value &&
      this.shown.value !== null &&
      !this.selecting.value &&
      this.dismissed.value !== this.shown.value.key,
  )
  protected readonly content = derived(() => this.selected.value.now ?? this.selected.value.last)
  protected readonly announce = derived(() => (words: string) => {
    this.said.value = { text: words, at: this.said.value.at + 1 }
  })
  protected readonly outside = derived(
    () =>
      (node: Node): Element | null =>
        [this.bar.value, this.status.value].find((part) => part?.contains(node) === true) ?? null,
  )
  protected readonly updateSelection = derived(() => () => {
    const found = this.root.value
      ? mapRichTextSelection(this.root.value, this.outside.value, this.drawing.value.value)
      : null
    if (found !== null) this.held.value.range = found.dom
    // A dismissal holds for one selection: once it collapses, the next one brings the bar back.
    else this.dismissed.value = null
    if (found === null) {
      if (this.selected.value.now !== null)
        this.selected.value = { now: null, last: this.selected.value.last }
      return
    }
    if (this.selected.value.now?.key === found.key && this.selected.value.now.text === found.text)
      return
    const mapping = { range: found.range, text: found.text, key: found.key }
    this.selected.value = { now: mapping, last: mapping }
  })
  protected readonly followSelection = derived(() => (element: HTMLElement) => {
    const page = element.ownerDocument
    const update = () => this.updateSelection.value()
    page.addEventListener('selectionchange', update)
    return () => page.removeEventListener('selectionchange', update)
  })
  protected readonly releaseSelecting = derived(() => (element: HTMLElement) => {
    const view = element.ownerDocument.defaultView
    const release = () => {
      this.selecting.value = false
    }
    view?.addEventListener('pointerup', release, true)
    view?.addEventListener('pointercancel', release, true)
    return () => {
      view?.removeEventListener('pointerup', release, true)
      view?.removeEventListener('pointercancel', release, true)
    }
  })
  protected readonly holdKeys = derived(() => (element: HTMLElement) => {
    const view = element.ownerDocument.defaultView
    const keys = (event: KeyboardEvent) => {
      const target = event.target
      if (event.isComposing || !(target instanceof Node)) return
      if (this.bar.value?.contains(target) === true) return
      const page = element.ownerDocument
      if (target !== page.body && target !== page.documentElement && !element.contains(target))
        return
      if (event.key === 'Escape') {
        event.preventDefault()
        if (this.shown.value !== null) this.dismissed.value = this.shown.value.key
      } else if (event.key === 'F10' && event.altKey) {
        event.preventDefault()
        enterToolbar(this.bar.value, this.barStops.value)
      }
    }
    view?.addEventListener('keydown', keys, true)
    return () => view?.removeEventListener('keydown', keys, true)
  })
  protected readonly restoreSelection = derived(() => () => {
    const range = this.held.value.range
    const selection = this.root.value?.ownerDocument.getSelection()
    if (range === null || selection === null || selection === undefined || !selection.isCollapsed)
      return
    selection.removeAllRanges()
    selection.addRange(range)
  })
  protected readonly leaveBar = derived(() => () => {
    if (this.shown.value !== null) this.dismissed.value = this.shown.value.key
    this.held.value.restoring = true
    this.restoreSelection.value()
  })
  protected readonly giveFocusBack = derived(() => () => {
    const to = this.held.value.cameFrom
    this.held.value.cameFrom = null
    const active = this.bar.value?.ownerDocument.activeElement
    if (to !== null && to.isConnected && this.bar.value?.contains(to) !== true)
      to.focus({ preventScroll: true })
    else if (active instanceof HTMLElement && this.bar.value?.contains(active) === true)
      active.blur()
    if (this.held.value.restoring) this.restoreSelection.value()
    this.held.value.restoring = false
  })
  protected readonly barLeave = derived(() => (event: FocusEvent) => {
    const to = event.relatedTarget
    if (to instanceof Node && (event.currentTarget as HTMLElement).contains(to)) return
    this.barFocus.value = false
    // A leaving bar is inert, and a browser that moves focus off it does so here.
    if (this.bar.value?.inert === true) this.giveFocusBack.value()
  })
  protected readonly cameFrom = derived(() => (event: FocusEvent) => {
    const from = event.relatedTarget
    if (from instanceof HTMLElement && this.bar.value?.contains(from) === true) return
    this.held.value.cameFrom = from instanceof HTMLElement ? from : null
  })
  protected readonly documentChanged = derived(() => () => {
    this.selected.value = { now: null, last: null }
    this.held.value.range = null
    const selection = this.root.value?.ownerDocument.getSelection()
    if (
      this.root.value === null ||
      this.root.value === undefined ||
      selection === null ||
      selection === undefined
    )
      return
    if (selection.rangeCount === 0 || selection.isCollapsed) return
    const range = selection.getRangeAt(0)
    if (
      this.root.value.contains(range.startContainer) ||
      this.root.value.contains(range.endContainer)
    )
      selection.collapseToEnd()
  })
  protected readonly measure = derived(() => () => {
    const selection = this.root.value?.ownerDocument.getSelection()
    if (this.root.value && selection && selection.rangeCount > 0) {
      const range = selection.getRangeAt(0)
      if (!range.collapsed && this.root.value.contains(range.commonAncestorContainer))
        return richTextSelectionBox(range)
    }
    return this.held.value.range === null ? null : richTextSelectionBox(this.held.value.range)
  })
  protected readonly placeBar = derived(
    () => () => placeSelectionBar(this.bar.value, this.measure.value()),
  )
  protected readonly barStops = derived(() => toolbarStop())
  protected readonly holdEscapeIn = derived(() => (element: HTMLElement) => {
    const view = element.ownerDocument.defaultView
    return view === null ? () => {} : holdToolbarEscape(view, () => this.bar.value)
  })
  protected readonly pressed = derived(() => (event: MouseEvent) => {
    const id = richTextPressedAnnotation(
      event.currentTarget as Element,
      event.target,
      event.detail,
      this.bar.value,
    )
    if (id !== null) this.$.emit(this.onAnnotationSelect, 'onAnnotationSelect', id)
  })
  protected readonly keyed = derived(() => (event: KeyboardEvent, phase: 'down' | 'up') => {
    const id = richTextKeyedAnnotation(event, phase)
    if (id !== null) this.$.emit(this.onAnnotationSelect, 'onAnnotationSelect', id)
  })
  protected readonly pressDown = derived(() => (event: PointerEvent) => {
    if (!(event.target instanceof Node) || this.bar.value?.contains(event.target) !== true)
      this.selecting.value = true
  })
  protected readonly barPresent = setup(() =>
    usePresence(
      () => this.barOpen.value,
      () => this.bar.value,
    ),
  )
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined
  private release3: (() => void) | undefined
  private release7: (() => void) | undefined
  private release8: (() => void) | undefined
  private release10: (() => void) | undefined
  private release11: (() => void) | undefined

  constructor() {
    this.$.owner = getters<RichTextContentOwner>({
      size: () => this.$p.size,
      pressable: () => this.pressable.value,
      routes: () => this.routes.value,
      navigate: () => this.navigate.value,
      entityNode: () => this.entityNode.value,
    })
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => this.offering.value,
      () => this.effect1(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    watchEffect(
      () => this.selecting.value,
      () => this.effect2(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    watchEffect(
      () => this.barOpen.value,
      () => this.effect3(),
      true,
    )
    watchEffect(
      () => this.docKey.value,
      () => this.effect4(),
      false,
    )
    watchEffect(
      () => this.barOpen.value,
      () => this.effect5(),
      false,
    )
    watchEffect(
      () => this.barOpen.value,
      () => this.effect6(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release7?.())
    watchEffect(
      () => this.barPresent.value(),
      () => this.effect7(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release8?.())
    watchEffect(
      () => this.barPresent.value(),
      () => this.effect8(),
      true,
    )
    watchEffect(
      () => [this.barOpen.value, this.selected.value],
      () => this.effect9(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release10?.())
    watchEffect(
      () => this.barOpen.value,
      () => this.effect10(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release11?.())
    mountEffect(() => this.effect11())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.size
  }

  protected e3() {
    return this.drawing.value.empty ? '' : undefined
  }

  protected h1($event: MouseEvent): void {
    if (this.pressable.value) {
      this.pressed.value($event)
    }
  }

  protected h2($event: KeyboardEvent): void {
    if (this.pressable.value) {
      this.keyed.value($event, 'down')
    }
  }

  protected h3($event: KeyboardEvent): void {
    if (this.pressable.value) {
      this.keyed.value($event, 'up')
    }
  }

  protected h4($event: PointerEvent): void {
    if (this.offering.value) {
      this.pressDown.value($event)
    }
  }

  protected e4() {
    return !this.drawing.value.empty
  }

  protected e5(): RichTextContentBlocksProps['blocks'] {
    if (this.drawing.value.empty) return undefined as never
    return this.drawing.value.blocks
  }

  protected e6() {
    return this.offering.value && this.barPresent.value()
  }

  protected e7() {
    if (!(this.offering.value && this.barPresent.value())) return undefined as never
    return selectionBar.bar
  }

  protected e8() {
    if (!(this.offering.value && this.barPresent.value())) return undefined as never
    return this.say.value.selectionBar
  }

  protected e9() {
    if (!(this.offering.value && this.barPresent.value())) return undefined as never
    return !this.barOpen.value ? 'closed' : undefined
  }

  protected e10() {
    if (!(this.offering.value && this.barPresent.value())) return undefined as never
    return presence(!this.barOpen.value ? true : undefined)
  }

  protected h5($event: KeyboardEvent): void {
    if (!(this.offering.value && this.barPresent.value())) return
    toolbarKeydown(
      $event.currentTarget as HTMLElement,
      $event,
      this.barStops.value,
      this.leaveBar.value,
    )
  }

  protected h6($event: FocusEvent): void {
    if (!(this.offering.value && this.barPresent.value())) return
    void (toolbarFocusIn($event.currentTarget as HTMLElement, $event, this.barStops.value),
    (this.barFocus.value = true))
  }

  protected h7($event: FocusEvent): void {
    if (!(this.offering.value && this.barPresent.value())) return
    void (toolbarFocusOut($event.currentTarget as HTMLElement, $event, this.barStops.value),
    this.barLeave.value($event))
  }

  protected h8($event: MouseEvent): void {
    if (!(this.offering.value && this.barPresent.value())) return
    toolbarPress($event.currentTarget as HTMLElement, $event)
  }

  protected e11() {
    if (!(this.offering.value && this.barPresent.value())) return undefined as never
    return styles.actions
  }

  protected h9($event: FocusEvent): void {
    if (!(this.offering.value && this.barPresent.value())) return
    this.cameFrom.value($event)
  }

  protected e12() {
    if (!(this.offering.value && this.barPresent.value())) return undefined as never
    return this.content.value !== null
  }

  protected e13() {
    if (!(this.offering.value && this.barPresent.value())) return undefined as never
    if (!(this.content.value !== null)) return undefined as never
    return bindSlot(this.$p.selectionActions, {
      range: this.content.value.range,
      text: this.content.value.text,
    })
  }

  protected e14() {
    return this.offering.value
  }

  protected e15() {
    if (!this.offering.value) return undefined as never
    return styles.status
  }

  protected e16() {
    if (!this.offering.value) return undefined as never
    return this.said.value.text !== ''
  }

  protected e17() {
    if (!this.offering.value) return undefined as never
    if (!(this.said.value.text !== '')) return undefined as never
    return this.said.value.at
  }

  protected e18() {
    if (!this.offering.value) return undefined as never
    if (!(this.said.value.text !== '')) return undefined as never
    return this.said.value.text
  }

  private effect1(): void {
    this.release1?.()
    const ran =
      this.offering.value && this.root.value
        ? this.followSelection.value(this.root.value)
        : () => {}
    this.release1 = () => {
      ran()
    }
  }

  private effect2(): void {
    this.release2?.()
    const ran =
      this.selecting.value && this.root.value
        ? this.releaseSelecting.value(this.root.value)
        : () => {}
    this.release2 = () => {
      ran()
    }
  }

  private effect3(): void {
    this.release3?.()
    const ran =
      this.barOpen.value && this.root.value ? this.holdKeys.value(this.root.value) : () => {}
    this.release3 = () => {
      ran()
    }
  }

  private effect4(): void {
    this.documentChanged.value()
  }

  private effect5(): void {
    void (
      !this.barOpen.value &&
      this.bar.value?.contains(this.bar.value.ownerDocument.activeElement) === true &&
      this.giveFocusBack.value()
    )
  }

  private effect6(): void {
    void (
      this.barOpen.value &&
      !this.barHeard.value &&
      ((this.barHeard.value = true), this.announce.value(this.say.value.selectionBarReady))
    )
  }

  private effect7(): void {
    this.release7?.()
    const run = () => {
      syncToolbarStop(this.bar.value, this.barStops.value)
    }
    const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
    for (const element of [this.bar.value])
      if (element)
        mutation?.observe(element, {
          childList: true,
          characterData: true,
          subtree: true,
          attributeFilter: ['disabled', 'aria-disabled', 'hidden', 'inert'],
        })
    this.release7 = () => {
      mutation?.disconnect()
    }
    run()
  }

  private effect8(): void {
    this.release8?.()
    const ran =
      this.barPresent.value() && this.bar.value ? this.holdEscapeIn.value(this.bar.value) : () => {}
    this.release8 = () => {
      ran()
    }
  }

  private effect9(): void {
    void (this.barOpen.value && this.placeBar.value())
  }

  private effect10(): void {
    this.release10?.()
    const ran =
      this.barOpen.value && this.bar.value
        ? followSelectionBar(this.bar.value, this.placeBar.value)
        : () => {}
    this.release10 = () => {
      ran()
    }
  }

  private effect11(): void {
    this.release11?.()
    const ran = !this.$.listening(this.onAnnotationSelect, 'onAnnotationSelect')
      ? () => {}
      : agentMember({
          member: 'RichTextContent',
          element: () => this.root.value,
          state: () => ({
            annotations: richTextAnnotations(this.drawing.value.value)
              .filter((annotation) => this.drawn.value(annotation.id))
              .map((annotation) => ({
                id: annotation.id,
                label: annotation.text,
                ...(this.drawing.value.stops.includes(annotation.id) ? {} : { disabled: true }),
              })),
            active: richTextAnnotations(this.drawing.value.value).some(
              (annotation) =>
                this.drawn.value(annotation.id) && annotation.id === this.$p.activeAnnotation,
            )
              ? (this.$p.activeAnnotation ?? null)
              : null,
          }),
          actions: {
            select: {
              argument: 'id',
              run: (value) =>
                (() => {
                  const stop = Array.from(
                    this.root.value?.querySelectorAll(RICH_TEXT_STOP) ?? [],
                  ).find((element) => element.getAttribute('data-annotation-id') === value)
                  if (stop === undefined)
                    throw new Error('That annotation has no highlight to press.')
                  agentPress(stop)
                })(),
            },
          },
        })
    this.release11 = () => {
      ran()
    }
  }
}
